// Just a pass-through vertex shader, nothing fancy here
const vert = `attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aTexCoord;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec2 vVertTexCoord;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertTexCoord = aTexCoord;
  }
`

const frag = `precision mediump float;
  varying highp vec2 vVertTexCoord;

  uniform sampler2D prev;
  uniform float time;

  // Noise functions
  // https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
  float rand(float n) {
    return fract(sin(n) * 43758.5453123);
  }
  float rand(vec2 n) { 
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
  }
  float noise(float p) {
    float fl = floor(p);
    float fc = fract(p);
    return mix(rand(fl), rand(fl + 1.0), fc);
  }
  float noise(vec2 n) {
    const vec2 d = vec2(0.0, 1.0);
    vec2 b = floor(n);
    vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
    return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
  }

	const int NUM_SAMPLES = 12;
  void main() {
    vec4 color = vec4(0., 0., 0., 0.);

		vec2 coord = gl_FragCoord.xy;

		vec2 flow = vec2(
			2.*noise(vVertTexCoord*4. + time*0.2)-1.,
			2.*noise(123. + vVertTexCoord*13. + time*0.3)-1.
		) * 0.0005;

		for (int i = 0; i < NUM_SAMPLES; i++) {
			float sampleOffset = float(i) * 123.456789;
			vec2 noiseOffset = vec2(
				fract(10. * noise(coord * 0.2) + sampleOffset) - 0.5,
				fract(10. * noise(coord * 0.2) + 10. + sampleOffset) - 0.5
			) * 0.0001;
			color += texture2D(prev, vVertTexCoord + flow + noiseOffset);
		}
		color /= float(NUM_SAMPLES);

		gl_FragColor = vec4(color.xyz, 1.);
  }
`

