let fluidShader
let canvas
let prevMouseX
let prevMouseY
function setup() {
	canvas = createCanvas(600, 600, WEBGL)
	fluidShader = createShader(vert, frag)

	background(0)

	noStroke()

	// Initial gradient
	beginShape(TRIANGLE_STRIP)

	fill('#a7e889')
	vertex(-width/2, -height/2)

	fill('#faf487')
	vertex(width/2, -height/2)

	fill('#87facc')
	vertex(-width/2, height/2)

	fill('#fad587')
	vertex(width/2, height/2)

	endShape()

	prevMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
	prevMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
}

function draw() {
	drawingContext.disable(drawingContext.DEPTH_TEST)

	const dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - prevMouseX
	const dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - prevMouseY
	const movement = Math.hypot(dx, dy)

	if (random() < movement/30 + 0.05) {
		const x = randomGaussian((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, 10 + abs(dx)*2)
		const y = randomGaussian((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2, 10 + abs(dy)*2)
		const r = abs(randomGaussian(0, 10)) * movement * 0.05 + 5
		fill(color(
			map(sin(frameCount*0.001 + 400), -1, 1, 0, 255),
			map(sin(frameCount*0.002 + 410), -1, 1, 0, 255),
			map(sin(frameCount*0.003 + 430), -1, 1, 0, 255),
		))
		circle(x, y, r)
	}

	prevMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
	prevMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))

	push()
	shader(fluidShader)
	fluidShader.setUniform('prev', canvas)
	fluidShader.setUniform('time', frameCount / 60)
	rectMode(CENTER)
	rect(0, 0, width, height)
	pop()
}
